1	import { relative } from 'node:path';
2	import { finding } from '../../../engine/checks/helpers/findings.mjs';
3	// Namespace imports throughout, and every constant read through a `typeof`
4	// guard: the engine lane and the pack lane converge on separate cycles, so this
5	// file spends windows beside an engine that predates one of the symbols below.
6	// A named import of an absent export is a link-time error that faults the whole
7	// pack; a guarded read simply drops that one advisory, which is the behaviour
8	// the older engine already has.
9	import * as settingsNames from '../../../engine/settings-file-names.mjs';
10	import * as repoContext from '../../../engine/checks/helpers/repo-context.mjs';
11	import * as renamedPacks from '../../../engine/pack_loader/renamed-packs.mjs';
12	import * as versionSpec from '../../../engine/version.mjs';
13	import * as servedBy from '../../../engine/served-by.mjs';
14	import * as findings from '../../../engine/checks/helpers/findings.mjs';
15	
16	// A declared-checks file the member wrote: its own local packs', a skill's included.
17	const LOCAL_DECLARED = /^\.claudinite\/local\/packs\/.*declared-checks\.json$/;
18	// A manifest the member wrote: its own local packs'.
19	const LOCAL_MANIFEST = /^\.claudinite\/local\/packs\/[^/]+\/pack\.mjs$/;
20	const RETIRED_FINGERPRINT = /^[ \t]*(detect|marker)[ \t]*:/m;
21	
22	// THE ADVISORY HALF OF EVERY DECLARATION-SHAPE TOLERANCE the engine still
23	// carries. Each of those tolerances lets a member's own file be read in a shape
24	// that has since been renamed, and each is removed one convergence window after
25	// this advisory ships (#1638) - the time a repo updating nightly needs to act on
26	// its own finding. Nothing was telling the repos, which is why the window needed
27	// the advisory first.
28	//
29	// The tolerances #1640 removed are no longer among them: the retired settings-file
30	// name, the `claudinite` and `maintenance` blocks, top-level `packConfig`,
31	// `taskScheduler.endpoints` and the `local_packs/` declaration prefix are read by
32	// nothing now, and a member still carrying one gets the settings-validity gate's
33	// blocking error instead of a note. What is left are the shapes that still resolve:
34	// a renamed or absorbed pack id (#1641), an integer version (#1912), the
35	// `updates` mechanism alias (#1643) and a check's `severity`, the retired name of
36	// its `on_fail`, in an override or a local pack.
37	//
38	// A tolerance with no advisory asks people to migrate off something they have no
39	// way of knowing they are on, so this rule fires in the repo that HOLDS the old
40	// shape rather than in the canon that tolerates it (basics' *Adding a legacy
41	// tolerance*). It reads the member's own declaration and stamp and names, per
42	// finding, the edit that moves it forward.
43	//
44	// ADVISORY, permanently. The old shape works — that is what a tolerance means —
45	// so a blocking finding would stop a member's build over something that is not
46	// broken. What the advisory buys is that the removal's gate can eventually read
47	// zero, which is the only way the tolerance ever comes out.
48	const rule = {
49	  id: 'legacy-shape-in-use',
50	  on_fail: 'advise',
51	  since: '2026-09-03',
52	  description: 'This repo\'s Claudinite declaration and stamp use no shape the engine only tolerates',
53	  why: 'every legacy shape here is read through a tolerance that comes out one convergence window after this advisory ships (#1638) - the canon cannot see which repos still carry the old shape, so a repo that does not act inside that window loses its mount rather than holding the removal up',
54	
55	  run(ctx) {
56	    const file = settingsNames.SETTINGS_FILE;
57	    if (!ctx.files.includes(file)) return [];              // not a member - inert
58	
59	    let raw;
60	    try { raw = JSON.parse(ctx.read(file) ?? ''); } catch { return []; }
61	    if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return [];
62	
63	    const out = [];
64	    const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
65	
66	    for (const key of Array.isArray(repoContext.LEGACY_CONFIG_KEYS) ? repoContext.LEGACY_CONFIG_KEYS : []) {
67	      if (raw[key] !== undefined) {
68	        flag(`the declaration carries the retired top-level "${key}" block`,
69	          'move its contents to their current homes — a pack\'s parameters to that pack\'s entry `config`, the stamp to `engineVersion` plus each entry\'s own `version`, delivery to `requirePrReview` — and delete the block');
70	      }
71	    }
72	
73	    for (const key of Array.isArray(repoContext.RETIRED_SCHEDULE_KEYS) ? repoContext.RETIRED_SCHEDULE_KEYS : []) {
74	      if (raw.taskScheduler?.[key] !== undefined) {
75	        flag(`taskScheduler.${key} is retired and nothing reads it`,
76	          'delete it: a task cadence measures whole UTC periods, and the scheduler workflow\'s own cron hours were written in when the file was scaffolded');
77	      }
78	    }
79	
80	    const entries = Array.isArray(raw.packs) ? raw.packs : [];
81	    const idOf = (e) => (typeof e === 'string' ? e : (e && typeof e === 'object' && typeof e.id === 'string' ? e.id : null));
82	    const renames = renamedPacks.RENAMED_PACKS ?? {};
83	
84	    for (const entry of entries) {
85	      const id = idOf(entry);
86	      if (id === null) continue;
87	      if (Object.hasOwn(renames, id)) {
88	        flag(`the pack entry "${id}" names a pack that has been renamed or absorbed`,
89	          `declare "${renames[id]}" instead — an id is matched literally when packs activate, so on the day the rename map comes out this entry activates nothing at all, the self-refresh included`);
90	      }
91	      if (typeof versionSpec.isLegacyVersion === 'function' && versionSpec.isLegacyVersion(entry?.version)) {
92	        flag(`the pack entry "${id}" is stamped with the pre-2026-08-20 integer version ${entry.version}`,
93	          'let the update restamp it — a date-anchored `<day>.<n>` says when, where a counter says only "behind by an unknown amount"; if the update has run and the integer is still here, this mount is not updating');
94	      }
95	    }
96	
97	    if (typeof versionSpec.isLegacyVersion === 'function' && versionSpec.isLegacyVersion(raw.engineVersion)) {
98	      flag(`engineVersion is the pre-2026-08-20 integer ${raw.engineVersion}`,
99	        'let the update restamp it — an integer sorts below every date-anchored version, so this mount prices itself as ancient against all of them');
100	    }
101	
102	    // A literal, not a read of the engine: `updates` left the vocabulary with #1643,
103	    // so there is no constant left to name it — and the member file that still says
104	    // it is exactly what this rule exists to find. The value is historical and
105	    // cannot move.
106	    if (raw.servedBy?.mechanism === 'updates') {
107	      flag('servedBy.mechanism is the retired alias "updates"',
108	        `write "${servedBy.VERSIONED_MECHANISM ?? 'versioned'}" — the alias left the vocabulary, so this declaration now reads as unrecognised; the update flows still run here, from the default rather than from anything this repo said`);
109	    }
110	
111	    // The check field `severity: "blocking" | "advisory"` is `on_fail: "block" |
112	    // "advise"` now, and the override values follow it. Only what the member wrote
113	    // is reported: a vendored pack's own spelling moves with its next update.
114	    const onFailOf = typeof findings.onFailOf === 'function' ? findings.onFailOf : null;
115	    const legacyValues = findings.LEGACY_ON_FAIL ?? {};
116	    if (onFailOf) {
117	      const overrides = [['the top-level "rules"', raw.rules],
118	        ...entries.map((e) => [`the "${idOf(e)}" pack entry`, e?.rules])];
119	      for (const [where, rules] of overrides) {
120	        if (rules === null || typeof rules !== 'object') continue;
121	        for (const [id, value] of Object.entries(rules)) {
122	          if (!Object.hasOwn(legacyValues, value)) continue;
123	          flag(`the override for "${id}" on ${where} is set to "${value}", the retired spelling`,
124	            `write "${onFailOf(value)}" - an override now takes "off", "advise" or "block"`);
125	        }
126	      }
127	
128	      for (const declared of ctx.files.filter((f) => LOCAL_DECLARED.test(f))) {
129	        let specs;
130	        const text = ctx.read(declared) ?? '';
131	        try { specs = JSON.parse(text); } catch { continue; }
132	        if (!Array.isArray(specs)) continue;
133	        for (const spec of specs) {
134	          if (!spec || typeof spec !== 'object' || spec.severity === undefined || spec.on_fail !== undefined) continue;
135	          const at = text.indexOf('"severity"', Math.max(0, text.indexOf(`"${spec.id}"`)));
136	          out.push(finding(rule, {
137	            file: declared,
138	            line: at < 0 ? null : text.slice(0, at).split('\n').length,
139	            what: `the declared check "${spec.id}" carries "severity", the retired name of its on_fail`,
140	            fix: `replace "severity": "${spec.severity}" with "on_fail": "${onFailOf(spec) ?? 'block" or "advise'}"`,
141	          }));
142	        }
143	      }
144	
145	      for (const pack of (ctx.packs ?? []).filter((p) => p.local || p.temp)) {
146	        for (const coded of [...(pack.rules ?? []), ...(pack.skillChecks ?? [])]) {
147	          if (coded.severity === undefined || coded.on_fail !== undefined || coded.spec) continue;
148	          out.push(finding(rule, {
149	            file: ctx.root && pack.dir ? relative(ctx.root, pack.dir) : pack.id,
150	            what: `the check "${coded.id}" in the local pack "${pack.id}" declares severity, the retired name of its on_fail`,
151	            fix: `replace severity: '${coded.severity}' with on_fail: '${onFailOf(coded) ?? 'block'}' in its rule object`,
152	          }));
153	        }
154	      }
155	    }
